"""The Truth Ledger: single source for the guide, the Reminders installer and the .ics."""

BRAND = "Be The Man"
PRODUCT = "The Truth Ledger"
LIST_NAME = "Be The Man: Truth Ledger"
TAGLINE = "Break the cycle. Build the system. Be the man."

# Default reminder times (24h). Change in the installer if your day is different.
TIMES = {"morning": (6, 30), "midday": (12, 30), "review": (19, 0), "evening": (21, 0)}

MIDDAY = ("Anything to correct since this morning? Correct it before 5 PM: "
          "\"Actually, that's not true. The truth is ___.\" Then log it tonight.")

LEDGER = ("THE LEDGER (10 min)\n"
          "1. Lies told today (#): what, to whom\n"
          "2. Lies caught before I spoke (#)\n"
          "3. Corrections made (#)\n"
          "4. The trigger: who, where, how tired I was, and the fear (failure / rejection / conflict / looking weak)\n"
          "5. The story in my head: \"If I tell the truth, ___ will happen.\"\n"
          "6. What actually happened when I told the truth\n"
          "7. Tomorrow's risk moment, written as an if-then: \"If ___, then I'll say ___.\"\n"
          "8. One line of prayer or thanks")

